using TerraRuntime.Core.Worlds;
using System.IO.Compression;using System.Reflection;using System.Text.Json;using TerraRuntime.Contracts.Runtime;using TerraRuntime.Core;using TerraRuntime.Core.Npcs;using TerraRuntime.Core.Projectiles;using TerraRuntime.Core.Worlds.Generation;using TerraRuntime.Gameplay.Npcs;using TerraRuntime.World;
namespace TerraRuntime.Tests;
public sealed class GenerationPyramidEntranceCursor1458Tests {
 static readonly JsonDocument Source=Load();
 public static IEnumerable<object[]> BoundaryCases(){for(int i=0;i<Source.RootElement.GetProperty("admission").GetArrayLength();i++)yield return [i];}
 [Theory,MemberData(nameof(BoundaryCases))]
 public void Pyramid_candidate_boundaries_use_actual_source_current_cursor(int index){var r=Source.RootElement.GetProperty("admission")[index];var candidates=r.GetProperty("candidates").EnumerateArray().Select(x=>new VanillaPyramidCandidate1458(x.GetInt32(),100)).ToArray();Assert.Equal(r.GetProperty("accepted").GetBoolean(),DungeonPass1458.IsOrdinaryPyramidCandidatePositionEligible(candidates,r.GetProperty("index").GetInt32(),r.GetProperty("width").GetInt32(),r.GetProperty("side").GetInt32(),r.GetProperty("cursor").GetInt32()));}
 [Theory,InlineData(1458),InlineData(42)]
 public void Actual_dungeon_pass_retains_source_cursor_for_later_pyramids(int seed){var expected=Source.RootElement.GetProperty("cursors").EnumerateArray().Single(x=>x.GetProperty("seed").GetInt32()==seed);var world=new Workspace(4200,1200);var npcs=new RuntimeNpcStore();var projectiles=new RuntimeProjectileStore();npcs.SetVanillaSpawnContextSource(()=>new VanillaNpcSpawnContext(1,0,false){WorldDifficulty=1});npcs.SetVanillaSpawnWetCollisionSource((x,y,w,h)=>VanillaWorldCollision.GetLiquidContacts(world.TileStore,x,y,w,h).Wet);Assert.True(world.TileStore.TryAttachTileEntities([],1000));world.AttachEntityEffects(new WorldGenerationEntityEffects1458(npcs,projectiles,true),0,1);using var cancellation=CancellationTokenSource.CreateLinkedTokenSource(TestContext.Current.CancellationToken);var capture=new Capture(world,cancellation);var request=new WorldGenerationRequest(Provider1458.GeneratorId,"PyramidCursorSource",(ulong)seed,4200,1200){SeedText=seed.ToString(),Options=new(WorldGenerationGameMode.Classic,WorldGenerationEvil.Corruption)};var result=RuntimeWorldGenerationExecutor.Execute(new Provider(new SourceBackedFinal1458(),capture),request,world,null,cancellation.Token);Assert.Equal("Cancelled",result.Status.ToString());Assert.Equal(expected.GetProperty("x").GetInt32(),capture.Cursor);Assert.Equal(expected.GetProperty("x").GetInt32(),capture.Entrance.X);Assert.Equal(expected.GetProperty("y").GetInt32(),capture.Entrance.Y);Assert.Equal(expected.GetProperty("grid").GetString(),GenerationNaturalPrefix49Tests.GridHash(world));Assert.Equal(expected.GetProperty("rng").GetString(),capture.Rng);}
 sealed class Capture(Workspace world,CancellationTokenSource cancellation){public int Cursor;public DungeonPoint1458 Entrance;public string? Rng;public void After(WorldGenerationPassDescriptor descriptor,IWorldGenerationPass inner,IWorldGenerationContext context){if(!descriptor.Id.Value.EndsWith("/Dungeon",StringComparison.Ordinal))return;var field=typeof(DungeonPass1458).GetField("state",BindingFlags.Instance|BindingFlags.NonPublic)!;var state=(DungeonState1458)field.GetValue(inner)!;Cursor=state.DungeonGenerationX;Entrance=world.VanillaDungeonGraph!.Components.Single(x=>x.Kind==DungeonComponentKind1458.Entrance).Start;Rng=GenerationNaturalPrefix49Tests.RandomHash(context.VanillaRandom!,false);cancellation.Cancel();}}
 sealed class Provider(IWorldGenerationProvider inner,Capture capture):IWorldGenerationProvider{public WorldGeneratorId Id=>inner.Id;public void BuildPlan(in WorldGenerationRequest request,IWorldGenerationPlanBuilder builder)=>inner.BuildPlan(in request,new Builder(builder,capture));}
 sealed class Builder(IWorldGenerationPlanBuilder inner,Capture capture):IWorldGenerationPlanBuilder{public void Add(WorldGenerationPassDescriptor descriptor,IWorldGenerationPass pass)=>inner.Add(descriptor,new Pass(descriptor,pass,capture));}
 sealed class Pass(WorldGenerationPassDescriptor descriptor,IWorldGenerationPass inner,Capture capture):IWorldGenerationPass{public void Execute(IWorldGenerationContext context){inner.Execute(context);capture.After(descriptor,inner,context);}}
 static JsonDocument Load(){using var raw=typeof(GenerationPyramidEntranceCursor1458Tests).Assembly.GetManifestResourceStream("GenerationPyramidEntranceCursor1458")!;using var gzip=new GZipStream(raw,CompressionMode.Decompress);return JsonDocument.Parse(gzip);}
}
